const fs=require('fs');
const p='output/solution.json';
const d=JSON.parse(fs.readFileSync(p,'utf8'));
const allowed=new Set(['none','Measurement Error','Missing Step','Order Error','Other','Preparation Error','Technique Error','Temperature Error','Timing Error']);
const lens={A:946.5,B:694.4,C:779.9,D:783.2,E:1044.3,F:652.1,G:809.7,H:608.4,I:1149.6,J:837.4,K:770.4,L:676.5,M:1020.7,N:603.0,O:687.5,P:928.9,Q:748.8,R:709.2,S:649.8,T:816.2,U:914.6,V:766.0};
let errs=[];
if("'!d||!Array.isArray(d.sequence)) errs.push('"'bad root shape');
for(let i=0;i<d.sequence.length;i++){
 const x=d.sequence[i], ks=Object.keys(x).sort().join(',');
 if(ks"'!=='"'error,id,t_end,t_start,video') errs.push('fields '+i+': '+ks);
 if("'!lens[x.video]) errs.push('"'video '+i);
 if("'!Number.isInteger(x.id)||x.id<1||x.id>84) errs.push('"'id '+i);
 if(typeof x.t_start"'!=='"'number'||typeof x.t_end"'!=='"'number'||x.t_start<0||x.t_end<x.t_start||x.t_end>lens[x.video]) errs.push('time '+i);
 if("'!allowed.has(x.error)) errs.push('"'error '+i);
}
const groups={};
for(const x of d.sequence)(groups[x.video]??=[]).push(x);
for(const [v,a] of Object.entries(groups)) for(let i=1;i<a.length;i++){
 const p=a[i-1],x=a[i];
 if(x.t_start<p.t_start || (x.t_start===p.t_start&&x.id<p.id)) errs.push('order '+v+' '+i);
}
const missing=Object.keys(lens).filter(v=>"'!groups[v]);
console.log('"'entries',d.sequence.length);
console.log('counts',Object.keys(lens).map(v=>v+':'+(groups[v]?.length||0)).join(' '));
console.log('missing',missing.join(',')||'none');
console.log('errors',errs.length?errs.join('\\n'):'none');
NODE"

