/bin/bash -lc "node - <<'NODE'
const fs=require('fs');
const f='output/solution.json';
const d=JSON.parse(fs.readFileSync(f,'utf8'));
const allowed=new Set(['none','Measurement Error','Missing Step','Order Error','Other','Preparation Error','Technique Error','Temperature Error','Timing Error']);
const lens={A:946.5,B:694.4,C:779.9,D:783.2,E:1044.3,F:652.1,G:809.7,H:608.4,I:1149.6,J:837.4,K:770.4,L:676.5,M:1020.7,N:603,O:687.5,P:928.9,Q:748.8,R:709.2,S:649.8,T:816.2,U:914.6,V:766};
const issues=[];
for(const [i,x] of d.sequence.entries()){
 if(Object.keys(x).sort().join(',')"'!=='"'error,id,t_end,t_start,video')issues.push('shape@'+i);
 if("'!(x.video in lens)||!Number.isInteger(x.id)||x.id<1||x.id>84||!allowed.has(x.error))issues.push('"'vocab@'+i);
 if("'!Number.isFinite(x.t_start)||!Number.isFinite(x.t_end)||x.t_start<0||x.t_end<x.t_start||x.t_end>lens[x.video])issues.push('"'range@'+i);
}
for(const v of Object.keys(lens)){
 const a=d.sequence.filter(x=>x.video===v);
 if("'!a.length)issues.push('"'missing '+v);
 for(let i=1;i<a.length;i++)if(a[i].t_start<a[i-1].t_start||(a[i].t_start===a[i-1].t_start&&a[i].id<a[i-1].id))issues.push('order '+v+'@'+i);
}
console.log(JSON.stringify({valid:issues.length===0,entries:d.sequence.length,videos:new Set(d.sequence.map(x=>x.video)).size,bytes:fs.statSync(f).size,issues},null,2));
NODE"

